`timescale 1ns / 1ps
// Generated by pipeline/make_tasks.py (sign-off). Reference: golden/reference (final_op_data__ref below).
module tb;
  reg tb_clk; integer tb_seed, tb_cyc, tb_mis, tb_perr, tb_b, tb_k, tb_ph; reg tb_started; reg [31:0] tb_r;
  reg [31:0] data_in;
  reg [1:0] vc_id;
  reg gnt_or;
  wire [31:0] data_out; wire [31:0] ref_data_out;
  final_op_data dut (.data_in(data_in), .vc_id(vc_id), .gnt_or(gnt_or), .data_out(data_out));
  final_op_data__ref ref_i (.data_in(data_in), .vc_id(vc_id), .gnt_or(gnt_or), .data_out(ref_data_out));
  always #5 tb_clk = ~tb_clk;
  function [31:0] tb_rand(input integer dummy); begin tb_rand = $random(tb_seed); end endfunction
  // flit: type in [30:29], VC in [28:27], destination row/column 0..3 in [7:4]/[3:0]
  function [31:0] tb_flit(input integer dummy); reg [31:0] r; begin r = $random(tb_seed);
    tb_flit = {1'b0, r[30:29], r[28:27], r[26:8], 2'b00, r[5:4], 2'b00, r[1:0]}; end endfunction
  task tb_prop(input [8*64:1] msg); begin tb_perr = tb_perr + 1;
    if (tb_perr <= 15) $display("FAIL property: %0s (t=%0t)", msg, $time); end endtask
  task tb_compare; begin
    for (tb_b = 0; tb_b < 32; tb_b = tb_b + 1)
      if (ref_data_out[tb_b] !== 1'bx && ref_data_out[tb_b] !== 1'bz && data_out[tb_b] !== ref_data_out[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 32;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: data_out = %h, expected %h", $time, tb_cyc, data_out, ref_data_out);
      end
  end endtask
  task tb_props; begin
  end endtask
  reg [31:0] tbc_p_data_out, tbc_t_data_out;
  integer tbc_outs, tbc_bits;
  task tb_cov; begin
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_data_out = tbc_t_data_out | ((ref_data_out ^ tbc_p_data_out) & ~(ref_data_out ^ ref_data_out)); tbc_p_data_out = ref_data_out;
  end endtask
  task tb_cov_report; begin tbc_outs = 0; tbc_bits = 0;
    if (|tbc_t_data_out) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 32; tb_b = tb_b + 1) if (tbc_t_data_out[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    $display("INFO coverage: %0d of 1 checked outputs toggled, %0d of 32 bits", tbc_outs, tbc_bits);
  end endtask
  initial begin
    tb_seed = 29; tb_clk = 0; tb_mis = 0; tb_perr = 0; tb_started = 0; tb_ph = 0; tb_k = 0;
    data_in = 0; vc_id = 0; gnt_or = 0;
    tbc_t_data_out = 0; tbc_p_data_out = 0;
    for (tb_cyc = 0; tb_cyc < 5000; tb_cyc = tb_cyc + 1) begin
      @(negedge tb_clk);
      data_in = tb_flit(0);
      vc_id = {tb_rand(0)};
      gnt_or = {tb_rand(0)};
      tb_started = (tb_cyc >= 6);
      #4 tb_ph = 0; tb_compare; tb_props; if (tb_started) tb_cov;
      @(posedge tb_clk); #4 tb_ph = 1; tb_compare; tb_props; if (tb_started) tb_cov;
    end
    tb_cov_report;
    if (tb_mis + tb_perr == 0) $display("ALL TESTS PASSED");
    else $display("FAIL: %0d mismatches, %0d property errors", tb_mis, tb_perr);
    $finish;
  end
endmodule

// ---- reference copy of the golden module (children come from lib/)
`timescale 1ns / 1ps





















module final_op_data__ref(data_in, vc_id, gnt_or, data_out);

input [31:0] data_in;
input [1:0] vc_id;
input gnt_or;
output [31:0] data_out;


assign data_out[31] = data_in[31];
assign data_out[30]  =  data_in[30] | !gnt_or;
assign data_out[29]  =  data_in[29] | !gnt_or;
assign data_out[28:27]  =  vc_id;	

assign data_out[26]  =  data_in[26] & gnt_or; 
assign data_out[25]  =  data_in[25] & gnt_or;
assign data_out[24]  =  data_in[24] & gnt_or;
assign data_out[23]  =  data_in[23] & gnt_or;
assign data_out[22]  =  data_in[22] & gnt_or;
assign data_out[21]  =  data_in[21] & gnt_or;
assign data_out[20]  =  data_in[20] & gnt_or;
assign data_out[19]  =  data_in[19] & gnt_or;
assign data_out[18]  =  data_in[18] & gnt_or;
assign data_out[17]  =  data_in[17] & gnt_or;
assign data_out[16]  =  data_in[16] & gnt_or;
assign data_out[15]  =  data_in[15] & gnt_or;
assign data_out[14]  =  data_in[14] & gnt_or;
assign data_out[13]  =  data_in[13] & gnt_or;
assign data_out[12]  =  data_in[12] & gnt_or;
assign data_out[11]  =  data_in[11] & gnt_or;
assign data_out[10]  =  data_in[10] & gnt_or;
assign data_out[9]  =  data_in[9] & gnt_or;
assign data_out[8]  =  data_in[8] & gnt_or;
assign data_out[7]  =  data_in[7] & gnt_or;
assign data_out[6]  =  data_in[6] & gnt_or;
assign data_out[5]  =  data_in[5] & gnt_or;
assign data_out[4]  =  data_in[4] & gnt_or;
assign data_out[3]  =  data_in[3] & gnt_or;
assign data_out[2]  =  data_in[2] & gnt_or;
assign data_out[1]  =  data_in[1] & gnt_or;
assign data_out[0]  =  data_in[0] & gnt_or;

endmodule
